<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue';
import Icon from './Icon.vue';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Row=Record<string,any>;
type Page={items:Row[];total:number};
type Profile={customer:Row;lifecycle:string;tags:Row[];history:Row[]};
type Access={contactRead:boolean;opportunities:boolean;tasks:boolean;activities:boolean;quotes:boolean;contracts:boolean;tickets:boolean;attachments:boolean;canPlan:boolean;canRecord:boolean};
const props=defineProps<{targetType:'CUSTOMER'|'LEAD'|'OPPORTUNITY';targetId:string;request:Request;readonly:boolean;manager:boolean;access:Access;download:(path:string,name:string)=>Promise<void>}>();
const emit=defineEmits<{close:[];openTarget:[type:'CUSTOMER'|'LEAD'|'OPPORTUNITY',id:string]}>();
const profile=ref<Profile|null>(null),target=ref<Row|null>(null),followups=ref<Row[]>([]),sections=reactive<Record<string,Page>>({});
const availableTags=ref<Row[]>([]),selectedTagIds=ref<string[]>([]);
const candidates=ref<Row[]>([]),busy=ref(false),error=ref(''),notice=ref(''),mergeTarget=ref<Row|null>(null),typedName=ref(''),mergeReason=ref(''),completing=ref<Row|null>(null),completeForm=reactive({content:'',resultCode:'CONNECTED',nextAction:'',attachmentId:''});
const stage=ref(''),stageReason=ref(''),plan=reactive({kind:'PLAN',content:'',when:'',resultCode:'CONNECTED',nextAction:'',attachmentId:''});
const labels:Record<string,string>={PROSPECT:'潜在客户',ACTIVE:'活跃客户',DORMANT:'沉睡客户',LOST:'流失客户',DECISION_MAKER:'决策人',INFLUENCER:'影响人',USER:'使用人',GATEKEEPER:'把关人',HIGH:'高',MEDIUM:'中',LOW:'低',PHONE:'电话',EMAIL:'邮件',WECHAT:'微信',IN_PERSON:'面谈',CONNECTED:'已联系',NO_ANSWER:'未接通',INTERESTED:'有意向',NOT_INTERESTED:'无意向',PENDING:'待完成',DONE:'已完成'};
const overdueCount=computed(()=>followups.value.filter(f=>f.kind==='PLAN'&&f.status==='PENDING'&&new Date(f.dueAt)<new Date()).length);
const title=computed(()=>profile.value?.customer.name||target.value?.companyName||target.value?.title||'档案');
const canWrite=computed(()=>!props.readonly&&(props.targetType==='CUSTOMER'?!!profile.value?.customer.canWrite:!!target.value?.canWrite));
const sources=computed(()=>[
 {key:'contacts',label:'联系人',path:'/contacts',allow:props.access.contactRead},
 {key:'opportunities',label:'商机',path:'/opportunities',allow:props.access.opportunities},
 {key:'tasks',label:'待办',path:'/tasks',allow:props.access.tasks},
 {key:'activities',label:'跟进记录',path:'/activities',allow:props.access.activities},
 {key:'quotes',label:'报价',path:'/quotes',allow:props.access.quotes},
 {key:'contracts',label:'合同',path:'/contracts',allow:props.access.contracts},
 {key:'tickets',label:'服务工单',path:'/tickets',allow:props.access.tickets},
 {key:'attachments',label:'附件',path:'/attachments',allow:props.access.attachments}
]);
const timeline=computed(()=>{const rows:Row[]=[];
 for(const f of followups.value)rows.push({id:f.id,kind:f.kind==='PLAN'?'跟进计划':'跟进记录',title:f.content,at:f.occurredAt||f.dueAt,detail:[labels[f.resultCode]||f.resultCode,f.nextAction,f.assigneeName].filter(Boolean).join(' · '),overdue:f.kind==='PLAN'&&f.status==='PENDING'&&new Date(f.dueAt)<new Date(),plan:f.kind==='PLAN'&&f.status==='PENDING'?f:null,attachmentId:f.attachmentId});
 for(const a of sections.activities?.items||[])rows.push({id:a.id,kind:'既有跟进',title:a.content,at:a.occurredAt,detail:a.actorName});
 for(const t of sections.tasks?.items||[])rows.push({id:t.id,kind:'既有待办',title:t.title,at:t.dueDate,detail:t.status==='PENDING'?'待完成':'已完成',overdue:t.overdue});
 for(const h of profile.value?.history||[])rows.push({id:h.createdAt+h.action,kind:'生命周期',title:h.action==='STAGE'?`${labels[h.fromStage]||h.fromStage} → ${labels[h.toStage]||h.toStage}`:'客户合并',at:h.createdAt,detail:h.reason});
 for(const a of sections.attachments?.items||[])rows.push({id:a.id,kind:'附件',title:a.fileName,at:a.createdAt,detail:'可下载',attachmentId:a.id});
 for(const o of sections.opportunities?.items||[])rows.push({id:o.id,kind:'商机',title:o.title,at:o.updatedAt,detail:o.stage});
 for(const q of sections.quotes?.items||[])rows.push({id:q.id,kind:'报价',title:q.title||q.quoteNumber,at:q.updatedAt,detail:q.status});
 for(const c of sections.contracts?.items||[])rows.push({id:c.id,kind:'合同',title:c.title||c.contractNumber,at:c.updatedAt,detail:c.status});
 for(const t of sections.tickets?.items||[])rows.push({id:t.id,kind:'服务工单',title:t.title,at:t.updatedAt,detail:t.status});
 return rows.sort((a,b)=>new Date(b.at||0).getTime()-new Date(a.at||0).getTime()).slice(0,250);
});
function attachmentName(id:string){return sections.attachments?.items?.find(a=>a.id===id)?.fileName||'客户附件';}
function downloadAttachment(id:string){return run(()=>props.download(`/attachments/${id}/download`,attachmentName(id)));}
function format(v:string){return v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—';}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function load(){availableTags.value=[];selectedTagIds.value=[];if(!props.access.canPlan&&props.access.canRecord)plan.kind='RECORD';profile.value=null;target.value=null;followups.value=[];for(const k of Object.keys(sections))delete sections[k];
 if(props.targetType==='CUSTOMER'){profile.value=await props.request<Profile>(`/customers/${props.targetId}/profile`);stage.value=profile.value.lifecycle;
  const tasks=sources.value.filter(x=>x.allow).map(async x=>{try{sections[x.key]=await props.request<Page>(`${x.path}?customerId=${props.targetId}&pageSize=100${x.key==='tasks'?'&status=':''}`);}catch{sections[x.key]={items:[],total:0};}});
  await Promise.all(tasks);
  if(profile.value.customer.canWrite){try{const ext=await props.request<{tags:Row[]}>(`/customers/${props.targetId}/extensions`);availableTags.value=ext.tags;selectedTagIds.value=ext.tags.filter(t=>t.assigned).map(t=>t.id);}catch{availableTags.value=[];}}
 }else{target.value=await props.request<Row>(`/${props.targetType==='LEAD'?'leads':'opportunities'}/${props.targetId}`);if(props.targetType==='OPPORTUNITY'&&props.access.attachments&&target.value.customerId){try{sections.attachments=await props.request<Page>(`/attachments?customerId=${target.value.customerId}&pageSize=100`);}catch{sections.attachments={items:[],total:0};}}}
 followups.value=await props.request<Row[]>(`/followups/${props.targetType}/${props.targetId}`);
}
function refresh(){return run(load);}
function saveTags(){return run(async()=>{await props.request(`/customers/${props.targetId}/extensions`,'PUT',{values:{},tagIds:selectedTagIds.value});await load();notice.value='客户标签已更新';});}
function findDuplicates(){return run(async()=>{candidates.value=await props.request<Row[]>(`/customers/${props.targetId}/duplicates`);notice.value=candidates.value.length?`发现 ${candidates.value.length} 个相似客户，请核对资料后再操作`:'未发现当前权限范围内的相似客户';});}
function setStage(){return run(async()=>{if(!stageReason.value.trim())throw new Error('请填写变更原因');await props.request(`/customers/${props.targetId}/lifecycle`,'PATCH',{expectedVersion:profile.value?.customer.version,stage:stage.value,reason:stageReason.value});stageReason.value='';await load();notice.value='生命周期已更新';});}
function merge(){return run(async()=>{if(!mergeTarget.value||typedName.value.trim()!==mergeTarget.value.name)throw new Error('请准确输入目标客户名称');if(!mergeReason.value.trim())throw new Error('请填写合并原因');const result=await props.request<Profile>(`/customers/${props.targetId}/merge`,'POST',{targetCustomerId:mergeTarget.value.id,sourceVersion:profile.value?.customer.version,targetVersion:mergeTarget.value.version,reason:mergeReason.value});mergeTarget.value=null;emit('openTarget','CUSTOMER',result.customer.id);});}
function createFollowup(){return run(async()=>{if(!plan.content.trim())throw new Error('请填写跟进内容');if(!plan.when)throw new Error('请填写计划或实际时间');const kind=plan.kind;await props.request('/followups','POST',{targetType:props.targetType,targetId:props.targetId,kind,content:plan.content,dueAt:kind==='PLAN'?new Date(plan.when).toISOString():null,occurredAt:kind==='RECORD'?new Date(plan.when).toISOString():null,resultCode:kind==='RECORD'?plan.resultCode:null,nextAction:plan.nextAction,attachmentId:kind==='RECORD'&&plan.attachmentId?plan.attachmentId:null});Object.assign(plan,{kind:props.access.canPlan?'PLAN':'RECORD',content:'',when:'',resultCode:'CONNECTED',nextAction:'',attachmentId:''});followups.value=await props.request<Row[]>(`/followups/${props.targetType}/${props.targetId}`);notice.value='跟进已保存';});}
function startComplete(item:Row){completing.value=item;Object.assign(completeForm,{content:item.content,resultCode:'CONNECTED',nextAction:item.nextAction||'',attachmentId:''});}
function complete(){return run(async()=>{if(!completing.value)return;const item=completing.value;await props.request(`/followups/plans/${item.id}/complete`,'POST',{expectedVersion:item.version,content:completeForm.content,resultCode:completeForm.resultCode,nextAction:completeForm.nextAction,attachmentId:completeForm.attachmentId||null});completing.value=null;followups.value=await props.request<Row[]>(`/followups/${props.targetType}/${props.targetId}`);notice.value='计划已完成并记录结果';});}
watch(()=>[props.targetType,props.targetId],()=>{candidates.value=[];mergeTarget.value=null;completing.value=null;notice.value='';run(load);},{immediate:true});
</script>

<template>
 <section class="profile-workspace">
  <header class="page-heading"><div><span class="eyebrow">CUSTOMER RELATIONSHIP 360°</span><h1>{{title}}</h1><p>{{targetType==='CUSTOMER'?'客户档案、关联业务与互动时间线':'跨层级跟进计划与结果记录'}} · {{targetType==='LEAD'?'线索':targetType==='OPPORTUNITY'?'商机':'客户'}}</p></div><div class="profile-actions"><button class="btn secondary" @click="emit('close')">返回列表</button><button class="btn secondary" :disabled="busy" @click="refresh"><Icon name="refresh" :size="16"/>刷新</button></div></header>
  <p v-if="error" class="profile-message error" role="alert">{{error}}</p><p v-if="notice" class="profile-message" role="status">{{notice}}</p>
  <div v-if="!profile&&!target" class="card profile-card">正在加载档案…</div>
  <template v-else>
   <section v-if="profile" class="card profile-card"><div class="profile-heading"><div><small>客户概览</small><h2>{{profile.customer.name}}</h2><p>{{profile.customer.industry}} · {{profile.customer.level}} 级 · {{profile.customer.region||'地区未填写'}} · 负责人 {{profile.customer.ownerName}}</p></div><span class="badge green">{{labels[profile.lifecycle]||profile.lifecycle}}</span></div>
    <div class="profile-tags"><span v-for="t in profile.tags" :key="t.id" :style="{borderColor:t.color}">{{t.name}}</span><span v-if="!profile.tags.length">暂无标签，可在行业配置中心设置</span></div>
    <form v-if="canWrite&&availableTags.length" class="profile-tag-form" @submit.prevent="saveTags"><fieldset><legend>客户标签</legend><label v-for="t in availableTags" :key="t.id"><input v-model="selectedTagIds" type="checkbox" :value="t.id"/><span :style="{borderColor:t.color}">{{t.name}}</span></label></fieldset><button class="btn secondary" :disabled="busy">保存标签</button></form>
    <p v-if="profile.customer.descriptionReadable&&profile.customer.description">{{profile.customer.description}}</p><p v-if="profile.customer.creditReadable">信用代码：{{profile.customer.creditCode||'未填写'}}</p>
    <form v-if="canWrite" class="profile-form-inline" @submit.prevent="setStage"><label>生命周期<select v-model="stage"><option value="PROSPECT">潜在客户</option><option value="ACTIVE">活跃客户</option><option value="DORMANT">沉睡客户</option><option value="LOST">流失客户</option></select></label><label>变更原因<input v-model="stageReason" maxlength="500" placeholder="必填"/></label><button class="btn secondary" :disabled="busy||stage===profile.lifecycle">更新阶段</button></form>
   </section>
   <section v-if="profile&&manager&&!readonly" class="card profile-card"><div class="profile-heading"><div><h2>查重与受控合并</h2><p>按客户名称或可读的信用代码查重。合并只允许来源客户没有商机、合同、工单等业务关联，记录与标签保留审计。</p></div><button class="btn secondary" :disabled="busy" @click="findDuplicates">检查重复客户</button></div><div v-for="c in candidates" :key="c.id" class="profile-duplicate"><span><strong>{{c.name}}</strong><small>{{c.ownerName}} · {{c.matchType==='CREDIT_CODE'?'信用代码匹配':'名称匹配'}}</small></span><button class="text-button" @click="mergeTarget=c;typedName='';mergeReason=''">选择合并目标</button></div>
    <form v-if="mergeTarget" class="profile-merge" @submit.prevent="merge"><strong>将“{{profile.customer.name}}”合并到“{{mergeTarget.name}}”</strong><p>来源客户会归档。输入目标名称与原因后提交；有业务关联时系统会拒绝并保持原数据。</p><label>输入目标客户全名<input v-model="typedName" required maxlength="200"/></label><label>合并原因<input v-model="mergeReason" required maxlength="500"/></label><div class="profile-actions"><button type="button" class="btn secondary" @click="mergeTarget=null">取消</button><button class="btn primary" :disabled="busy">确认合并</button></div></form>
   </section>
   <section v-if="profile" class="profile-summary"><div v-for="s in sources.filter(x=>x.allow)" :key="s.key" class="card profile-count"><span>{{s.label}}</span><strong>{{sections[s.key]?.total??0}}</strong></div></section>
   <div class="profile-columns"><section class="card profile-card"><h2>跟进计划与记录 <span v-if="overdueCount" class="badge profile-overdue">{{overdueCount}} 项逾期</span></h2><p class="profile-muted">支持线索、客户、商机三个层级；计划完成后会留下结果记录。</p>
     <form v-if="canWrite&&(access.canPlan||access.canRecord)" class="profile-followup-form" @submit.prevent="createFollowup"><label>类型<select v-model="plan.kind"><option v-if="access.canPlan" value="PLAN">跟进计划</option><option v-if="access.canRecord" value="RECORD">跟进记录</option></select></label><label>{{plan.kind==='PLAN'?'计划时间':'实际时间'}}<input v-model="plan.when" type="datetime-local" required/></label><label class="wide">内容<textarea v-model="plan.content" rows="3" maxlength="4000" required placeholder="需求、沟通要点或待跟进事项"/></label><label v-if="plan.kind==='RECORD'">跟进结果<select v-model="plan.resultCode"><option value="CONNECTED">已联系</option><option value="NO_ANSWER">未接通</option><option value="INTERESTED">有意向</option><option value="NOT_INTERESTED">无意向</option><option value="OTHER">其他</option></select></label><label>下一步行动<input v-model="plan.nextAction" maxlength="1000"/></label><label v-if="plan.kind==='RECORD'&&sections.attachments?.items?.length">关联附件<select v-model="plan.attachmentId"><option value="">无附件</option><option v-for="a in sections.attachments.items" :key="a.id" :value="a.id">{{a.fileName}}</option></select></label><button class="btn primary" :disabled="busy">保存跟进</button></form>
     <form v-if="completing" class="profile-followup-form" @submit.prevent="complete"><strong class="wide">完成计划并登记实际结果</strong><label class="wide">实际沟通内容<textarea v-model="completeForm.content" rows="3" maxlength="4000" required/></label><label>跟进结果<select v-model="completeForm.resultCode"><option value="CONNECTED">已联系</option><option value="NO_ANSWER">未接通</option><option value="INTERESTED">有意向</option><option value="NOT_INTERESTED">无意向</option><option value="OTHER">其他</option></select></label><label>下一步行动<input v-model="completeForm.nextAction" maxlength="1000"/></label><label v-if="sections.attachments?.items?.length">关联附件<select v-model="completeForm.attachmentId"><option value="">无附件</option><option v-for="a in sections.attachments.items" :key="a.id" :value="a.id">{{a.fileName}}</option></select></label><div class="profile-actions wide"><button type="button" class="btn secondary" @click="completing=null">取消</button><button class="btn primary" :disabled="busy">完成并保存记录</button></div></form>
     <div v-for="f in followups.slice(0,20)" :key="f.id" class="profile-row"><div><strong>{{f.kind==='PLAN'?'计划':'记录'}} · {{f.content}}</strong><small>{{format(f.occurredAt||f.dueAt)}} · {{f.assigneeName}} · {{labels[f.resultCode]||labels[f.status]||f.status}}</small><p v-if="f.nextAction">下一步：{{f.nextAction}}</p></div><button v-if="f.canComplete&&!readonly" class="text-button" :disabled="busy" @click="startComplete(f)">完成并记录</button></div><p v-if="!followups.length" class="profile-muted">暂无跟进计划或记录。</p>
   </section><section class="card profile-card"><h2>关系与业务</h2><div v-for="c in sections.contacts?.items||[]" :key="c.id" class="profile-row"><div><strong>{{c.name}} <span v-if="c.primary" class="badge green">首选</span></strong><small>{{c.jobTitle||'职位未填写'}} · {{labels[c.decisionRole]||'其他'}} · 影响力 {{labels[c.influence]||'未评估'}} · {{labels[c.contactPreference]||'不限'}}</small><small>{{c.phone||c.email||'未填联系方式'}}</small></div></div>
     <div v-for="o in sections.opportunities?.items||[]" :key="o.id" class="profile-row"><div><strong>{{o.title}}</strong><small>商机 · {{o.stage}} · 下一步 {{o.nextAction||'未填写'}}</small></div><button class="text-button" @click="emit('openTarget','OPPORTUNITY',o.id)">查看跟进</button></div>
     <div v-for="s in sources.filter(x=>x.allow&&!['contacts','opportunities','activities','tasks','attachments'].includes(x.key))" :key="s.key" class="profile-row"><strong>{{s.label}}</strong><span>{{sections[s.key]?.total??0}} 条</span></div><p v-if="!sources.some(x=>x.allow)" class="profile-muted">当前角色没有关联模块读取权限。</p>
   </section></div>
   <section class="card profile-card"><h2>统一时间线</h2><p class="profile-muted">汇总当前身份可读的跟进、待办、商机、交易、服务和附件。单类模块最多展示最近 100 条。</p><div v-for="item in timeline" :key="item.kind+item.id" class="profile-time-item" :class="{overdue:item.overdue}"><time>{{format(item.at)}}</time><span class="badge neutral">{{item.kind}}</span><div><strong>{{item.title}}</strong><small>{{item.detail||'—'}}</small></div><button v-if="item.attachmentId&&access.attachments" class="text-button" :disabled="busy" @click="downloadAttachment(item.attachmentId)">下载附件</button></div><p v-if="!timeline.length" class="profile-muted">暂无可见互动记录。</p></section>
  </template>
 </section>
</template>

<style scoped>
